/** Update `key value` (whitespace-separated) lines in place; append missing keys. */
function updateConvars(content: string, updates: Record<string, string>): string {
  const lines = content.split(/\r?\n/);
  const seen = new Set<string>();
  for (let i = 0; i < lines.length; i++) {
    const t = lines[i].trim();
    if (!t || t.startsWith("//") || t.startsWith("#")) continue;
    const sp = t.search(/\s/);
    const key = sp < 0 ? t : t.slice(0, sp);
    if (Object.prototype.hasOwnProperty.call(updates, key)) {
      lines[i] = `${key} ${updates[key]}`;
      seen.add(key);
    }
  }
  for (const k of Object.keys(updates)) {
    if (!seen.has(k)) lines.push(`${k} ${updates[k]}`);
  }
  return lines.join("\n");
}

const bool = (v: unknown) => (v === true || v === "true" || v === "on" ? "true" : "false");

// ---------------------------------------------------------------------------
// Container recreation — shared by every family whose image takes its settings
// from ENVIRONMENT VARIABLES rather than an editable config file
// ---------------------------------------------------------------------------

/**
 * Read a container's current environment as a map.
 *
 * Recreating a container means re-supplying its WHOLE environment, not just the
 * keys being changed: the images this is used for get most of their defaults
 * from their own Dockerfile `ENV`s, and dropping those would silently reset
 * settings the customer never touched. `PATH` is excluded — the image always
 * injects a correct one, and carrying ours over would be wrong.
 */
async function readContainerEnv(conn: Client, container: string): Promise<Map<string, string> | null> {
  const inspect = await execRemote(conn, `docker inspect ${container} --format '{{json .Config.Env}}'`);
  if (inspect.code !== 0) return null;
  let envArr: string[];
  try {
    envArr = JSON.parse(inspect.stdout.trim());
  } catch {
    return null;
  }
  const envMap = new Map<string, string>();
  for (const entry of envArr) {
    const idx = entry.indexOf("=");
    if (idx < 0) continue;
    envMap.set(entry.slice(0, idx), entry.slice(idx + 1));
  }
  envMap.delete("PATH");
  return envMap;
}

/** The exact image reference (repo:tag) a running container was created from. */
async function readContainerImage(conn: Client, container: string): Promise<string | null> {
  const res = await execRemote(conn, `docker inspect ${container} --format '{{.Config.Image}}'`);
  if (res.code !== 0) return null;
  const image = res.stdout.trim();
  return image || null;
}

/** Write an env map to a root-only `--env-file` on the guest. */
async function writeEnvFile(conn: Client, sftp: SFTPWrapper, path: string, envMap: Map<string, string>): Promise<void> {
  const content = Array.from(envMap.entries()).map(([k, v]) => `${k}=${v.replace(/\r?\n/g, " ")}`).join("\n") + "\n";
  await sftpWrite(sftp, path, content);
  await execRemote(conn, `chmod 600 '${shq(path)}'`);
}

