      "/opt/dayz/serverfiles/serverDZ.cfg",
    ],
    ["/opt/dayz"],
    "serverDZ.cfg"
  );
  if (!path) {
    return {
      ok: false,
      applied: [],
      notes: ["Could not locate serverDZ.cfg — nothing was changed (a restart is needed once the config path is confirmed against a live server)."],
    };
  }

  const existing = await sftpRead(sftp, path);
  if (existing == null) {
    return { ok: false, applied: [], notes: [`serverDZ.cfg disappeared at ${path} — nothing was changed.`] };
  }

  const flatUpdates: Record<string, string> = {};
  for (const key of ["hostname", "password", "passwordAdmin", "maxPlayers"]) {
    if (v[key] === undefined || v[key] === null) continue;
    flatUpdates[key] = String(v[key]);
  }
  const missionTemplate = v["missionTemplate"] != null ? String(v["missionTemplate"]) : undefined;

  const next = updateDayZConfig(existing, flatUpdates, missionTemplate);
  await sftpWrite(sftp, path, next);

  const changedCount = Object.keys(flatUpdates).length + (missionTemplate !== undefined ? 1 : 0);
  const applied: string[] = [`Wrote ${changedCount} setting(s) to ${path}.`];

  // serverDZ.cfg has no hot-reload/RCON push path (unlike Minecraft) — every
  // field here needs a restart, always. Through whichever supervisor owns
  // the container (see resolveGameUnit's own comment for why a bare `docker
  // restart` is wrong on a systemd-wrapped server).
  const unit = await resolveGameUnit(conn, "dayz");
  const restart = await execRemote(conn, unit ? `systemctl restart '${shq(unit)}'` : `docker restart ${DAYZ_CONTAINER}`);
  const notes: string[] =
    restart.code === 0
      ? ["Restarted the server to apply the new settings — any connected players were disconnected and can rejoin now."]
      : ["Wrote the new settings, but the restart could not be confirmed — restart the server manually from the Power tab."];

  return { ok: true, applied, notes };
}

// ---------------------------------------------------------------------------
// Rescue: pin a (crash-looping) Minecraft server to an exact jar — used by
// scripts/mc-pin-jar.ts. Same stage → env → recreateGameContainer (with its
// rollback) path as applyMinecraft above; never touches the world data.
// ---------------------------------------------------------------------------

const GUEST_JAR_RE = /^[A-Za-z0-9][A-Za-z0-9._+-]{0,150}\.jar$/;

export type PinTarget =
  | { kind: "mirror"; plan: PinPlan }
  | { kind: "guest-local"; type: PinPlan["type"]; mcVersion: string; jar: string };

export async function pinMinecraftServer(
  server: SshServer,
  target: PinTarget,
  variantForFallback: string,
): Promise<{ ok: boolean; notes: string[]; sha256?: string; build?: string }> {
  return withSsh(server, async (conn, sftp) => {
    const notes: string[] = [];
    const envMap = await readContainerEnv(conn, MINECRAFT_CONTAINER);
    if (!envMap) return { ok: false, notes: ["no `mc` container on this server (nothing to re-create)"] };
    let env: Record<string, string>;
    let version: string;
    let sha256: string;
    let build: string;
    if (target.kind === "guest-local") {
      if (!GUEST_JAR_RE.test(target.jar) || !/^[0-9A-Za-z][0-9A-Za-z._+-]{0,40}$/.test(target.mcVersion)) {
        return { ok: false, notes: ["bad jar name or version"] };
      }
      const h = await execRemote(conn, `test -f '/opt/mc/${target.jar}' && sha256sum '/opt/mc/${target.jar}' | cut -d' ' -f1`);
      sha256 = h.stdout.trim();
      if (h.code !== 0 || !/^[a-f0-9]{64}$/.test(sha256)) return { ok: false, notes: [`/opt/mc/${target.jar} not found on the guest`] };
      const head = await execRemote(conn, `head -c 2 '/opt/mc/${target.jar}'`);
      if (head.stdout !== "PK") return { ok: false, notes: [`/opt/mc/${target.jar} is not a jar`] };
      build = "guest-local";
      version = target.mcVersion;
      env = pinnedEnv({ type: target.type, mcVersion: version, build, fileName: target.jar, sha256 }, `/data/${target.jar}`);
      notes.push(`pinned to the jar already on the server: /opt/mc/${target.jar} (sha256 ${sha256.slice(0, 16)}…)`);
    } else {
      const st = await execRemote(conn, stageScript(target.plan, variantForFallback), 16 * 60_000);
      if (!/NXEON_MCJAR staged/.test(st.stdout)) return { ok: false, notes: [`staging failed on the guest: ${(st.stdout + st.stderr).slice(-300)}`] };
      env = pinnedEnv(target.plan);
      version = target.plan.mcVersion;
      sha256 = target.plan.sha256;
      build = target.plan.build;
      notes.push(`staged ${target.plan.type} ${version} build ${build} from the mirror (sha256 verified on the guest)`);
    }
    applyPinEnv(envMap, env);
    envMap.set("VERSION", version);
    envMap.delete("JAVA_VERSION");
    await writeEnvFile(conn, sftp, "/root/mc.env", envMap);
    const res = await recreateGameContainer(conn, {
      family: "minecraft",
      container: MINECRAFT_CONTAINER,
      runFlags: MINECRAFT_RUN_FLAGS,
      image: minecraftImageForVersion(version),
    });
    if (!res.ok) return { ok: false, notes: [...notes, res.note] };
    notes.push(`container re-created on ${minecraftImageForVersion(version)} and running`);
    return { ok: true, notes, sha256, build };
  });
}

/** Read-only: the `mc` container's image + the env keys that decide which jar runs (scripts/mc-pin-jar.ts --inspect). */
export async function inspectMinecraftContainer(server: SshServer): Promise<{ image: string | null; env: Record<string, string>; jars: string[] } | null> {
  return withSsh(server, async (conn) => {
    const envMap = await readContainerEnv(conn, MINECRAFT_CONTAINER);
    if (!envMap) return null;
    const keep = ["TYPE", "VERSION", "NXEON_MCJAR", "CUSTOM_SERVER", "PAPER_CUSTOM_JAR", "FABRIC_LAUNCHER", "FORGE_INSTALLER", "NEOFORGE_INSTALLER", "FAMILY"];
    const env = Object.fromEntries([...envMap.entries()].filter(([k]) => keep.includes(k)));
    const ls = await execRemote(conn, "ls -1 /opt/mc/*.jar /opt/mc/.nxeon/jars/*.jar 2>/dev/null | head -20");
    return { image: await readContainerImage(conn, MINECRAFT_CONTAINER), env, jars: ls.stdout.split("\n").filter(Boolean) };
  });
}

