  /** writeFile throws for this path */
  writeThrows?: string;
  container?: string;
  unit?: string;
};

export const IMAGE_ENV = ["PATH=/usr/bin", "DOTNET=9"];

export function tokenize(cmd: string): string[] {
  const out: string[] = [];
  const re = /'((?:[^']|'\\'')*)'|(\S+)/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(cmd))) out.push(m[1] !== undefined ? m[1].replace(/'\\''/g, "'") : m[2]);
  return out;
}

export function fakeGuest(opts: FakeOpts = {}) {
  const name = opts.container ?? "terraria";
  const unit = opts.unit ?? "terraria.service";
  const files = new Map<string, string>(Object.entries(opts.files ?? {}));
  const containers = new Map<string, FakeContainer>();
  const log: string[] = [];
  const st = { active: opts.active ?? true, created: 0 };
  containers.set(name, {
    image: "ryshe/terraria:latest",
    env: [...IMAGE_ENV, "WORLD_FILENAME=nxeon.wld"],
    cmd: ["-autocreate", "2", "-worldname", "Nxeon", "-additionalplugins", "/tshock/CustomPlugins"],
    binds: ["/opt/terraria:/root/.local/share/Terraria/Worlds", "/opt/terraria:/tshock/tshock", "/opt/terraria-plugins:/tshock/CustomPlugins"],
    ports: { "7777/tcp": [{ HostIp: "", HostPort: "7777" }] },
    running: st.active,
  });
  const newOnes = new Set<FakeContainer>();
  let corrupted = false;
  const ok = (stdout = ""): ExecResult => ({ code: 0, stdout, stderr: "" });
  const bad = (stderr = "err"): ExecResult => ({ code: 1, stdout: "", stderr });

  function one(part: string): ExecResult {
    part = part.replace(/>\/dev\/null( 2>&1)?|2>\/dev\/null/g, "").trim();
    if (!part) return ok();
    const t = tokenize(part);
    if (t[0] === "docker" && t[1] === "inspect" && part.includes("{{json .}}")) {
      const c = containers.get(t[2]);
      if (!c) return bad("No such object");
      return ok(JSON.stringify({
        Config: { Env: c.env, Image: c.image, Cmd: c.cmd, Entrypoint: ["/tshock/bootstrap.sh"], User: "" },
        HostConfig: { Binds: c.binds, PortBindings: c.ports, LogConfig: { Config: { "max-size": "10m", "max-file": "3" } } },
      }));
    }
    if (t[0] === "docker" && t[1] === "image" && t[2] === "inspect") return ok(JSON.stringify({ Env: IMAGE_ENV, Entrypoint: ["/tshock/bootstrap.sh"] }));
    if (t[0] === "docker" && t[1] === "inspect" && t[2] === "-f") {
      const c = containers.get(t[4]);
      return ok(c?.running ? "true" : "false");
    }
    if (t[0] === "systemctl" && t[1] === "is-active") return ok(st.active ? "active\n" : "inactive\n");
    if (t[0] === "systemctl" && t[1] === "stop") {
      st.active = false;
      const c = containers.get(name);
      if (c) c.running = false;
      return ok();
    }
    if (t[0] === "systemctl" && t[1] === "start") {
      const c = containers.get(name);
      if (!c) return bad("no container");
      if (opts.startFailsForNew && newOnes.has(c)) return bad("start failed");
      c.running = true;
      st.active = true;
      return ok();
    }
    if (t[0] === "docker" && t[1] === "rm") {
      containers.delete(t[3]);
      return ok();
    }
    if (t[0] === "docker" && t[1] === "rename") {
      const c = containers.get(t[2]);
      if (!c) return bad("No such container");
      containers.delete(t[2]);
      containers.set(t[3], c);
      return ok();
    }
    if (t[0] === "docker" && (t[1] === "update" || t[1] === "stop")) return ok();
    if (t[0] === "docker" && t[1] === "create") {
      if (opts.createFails) return bad("create failed");
      const get = (flag: string) => t.flatMap((x, i) => (x === flag ? [t[i + 1]] : []));
      const envFile = get("--env-file")[0];
      const fromFile = (files.get(envFile) ?? "").split("\n").filter(Boolean);
      const envKeys = new Set(fromFile.map((l) => l.split("=")[0]));
      const imgIdx = t.findIndex((x, i) => i > 3 && !x.startsWith("-") && t[i - 1] !== "--name" && !["--log-opt", "-p", "-v", "--env-file", "--user", "--entrypoint"].includes(t[i - 1]));
      const c: FakeContainer = {
        image: t[imgIdx],
        env: [...IMAGE_ENV.filter((e) => !envKeys.has(e.split("=")[0])), ...fromFile],
        cmd: t.slice(imgIdx + 1),
        binds: get("-v").sort(),
        ports: {},
        running: false,
      };
      for (const p of get("-p")) {
        const m = /^(?:(.*):)?(\d+):(\d+)\/(\w+)$/.exec(p)!;
        (c.ports[`${m[3]}/${m[4]}`] ??= []).push({ HostIp: m[1] ?? "", HostPort: m[2] });
      }
      containers.set(t[get("--name").length ? t.indexOf("--name") + 1 : 0], c);
      newOnes.add(c);
      st.created++;
      return ok("abc123");
    }
    if (t[0] === "install") { files.set(t[t.length - 1], ""); return ok(); }
    if (t[0] === "rm" && t[1] === "-f") { for (const f of t.slice(2)) files.delete(f); return ok(); }
    if (t[0] === "cp") { const src = files.get(t[2]); if (src === undefined) return bad("no src"); files.set(t[3], src); return ok(); }
    if (t[0] === "test" && t[1] === "-f") return files.has(t[2]) ? ok() : bad();
    return bad(`unhandled: ${part}`);
  }

  const guest: Guest = {
    async exec(cmd) {
      log.push(cmd);
      let last: ExecResult = ok();
      for (const part of cmd.split(/\s*(?:;|&&)\s*(?=docker|systemctl|rm|install|cp|test|echo|$)/)) {
        last = one(part);
        if (last.code !== 0 && /&&/.test(cmd) && !/;/.test(cmd)) return last;
      }
      return last;
    },
    async readFile(path) {
      return files.get(path) ?? null;
    },
    async writeFile(path, content) {
      log.push(`write ${path}`);
      if (opts.writeThrows === path) throw new Error("disk full");
      if (opts.corruptWrite === path && !corrupted) { corrupted = true; files.set(path, "{ not json"); return; }
      files.set(path, content);
    },
  };
  return { guest, files, containers, log, st, name, unit };
}
