import type { GameConfigApplierSpec } from "../game-config-appliers";

/**
 * Arma Reforger (sknnr/arma-reforger-server) — PURE half. Every schema field IS
 * a documented env var of the image (README, "any environment variable above
 * that has a default will override what is in your config file"), and the
 * provisioning script already declares each as `-e NAME=`, so a fresh install /
 * reinstall bakes them via applyGameConfigEnv. A Settings save recreates the
 * container with the new env (keeping its volume), the same safe swap as Terraria.
 * ADMIN_PASSWORD is deliberately not a field (minted per server at provision) and
 * is carried over untouched.
 */
export const ARMAREFORGER_SPEC: GameConfigApplierSpec = {
  family: "armareforger",
  fields: {
    SERVER_NAME: { when: "recreate" },
    SERVER_PASSWORD: { when: "recreate", secret: true },
    MAX_PLAYERS: { when: "recreate" },
    SCENARIO_ID: { when: "recreate", note: "The server downloads the scenario on start, so the restart can take a minute or two." },
    BATTLEYE: { when: "recreate" },
    ADMINS: { when: "recreate" },
    VISIBLE: { when: "recreate" },
    RCON_PASSWORD: { when: "recreate", secret: true, note: "Blank turns the BattlEye RCON console off." },
  },
};

export const ARMAREFORGER_CONTAINER = "armareforger";

type V = Record<string, string | number | boolean | undefined>;
const BOOLS = new Set(["BATTLEYE", "VISIBLE"]);

/** Env changes for the touched fields (schema key == env var name). */
export function armaEnv(values: V, touched: readonly string[]): Record<string, string> {
  const env: Record<string, string> = {};
  for (const k of touched) {
    if (!(k in ARMAREFORGER_SPEC.fields)) continue;
    env[k] = BOOLS.has(k) ? (values[k] === true || values[k] === "true" ? "true" : "false") : String(values[k] ?? "");
  }
  return env;
}
