import type { GameConfigApplierSpec } from "../game-config-appliers";

/**
 * ETS2 / ATS Convoy server (lshallo/ets2-convoy-server, lshallo/ats-convoy-server) — PURE half.
 *
 * Read off the image's own ets_server_entrypoint.py: with ETS_SERVER_WRITE_CONFIG
 * (default true) the entrypoint REGENERATES server_config.sii from the env on every
 * start, so the env is the single source of truth and recreating the container with
 * new env is the whole mechanism (no file is edited). Booleans are read with
 * "yes/true/on/1". The two games differ only in the env prefix (ETS_ / ATS_).
 */
const SHARED: Record<string, { when: "recreate"; secret?: boolean; note?: string }> = {
  lobby_name: { when: "recreate" },
  description: { when: "recreate" },
  welcome_message: { when: "recreate" },
  password: { when: "recreate", secret: true },
  max_players: { when: "recreate" },
  player_damage: { when: "recreate" },
  traffic: { when: "recreate" },
  force_speed_limiter: { when: "recreate" },
  name_tags: { when: "recreate" },
  server_logon_token: { when: "recreate", secret: true, note: "The server re-checks for game updates when it starts, so the restart can take a minute or two." },
  moderator_list: { when: "recreate" },
};

export function convoySpec(family: "ets2" | "ats"): GameConfigApplierSpec {
  return { family, fields: Object.fromEntries(Object.entries(SHARED).map(([k, v]) => [k, { ...v }])) };
}

/** schema field -> env-var suffix (after ETS_ / ATS_). */
export const CONVOY_ENV_SUFFIX: Record<string, string> = {
  lobby_name: "SERVER_NAME",
  description: "SERVER_DESCRIPTION",
  welcome_message: "SERVER_WELCOME_MESSAGE",
  password: "SERVER_PASSWORD",
  max_players: "SERVER_MAX_PLAYERS",
  player_damage: "SERVER_PLAYER_DAMAGE",
  traffic: "SERVER_TRAFFIC",
  force_speed_limiter: "SERVER_FORCE_SPEEDLIMITER",
  name_tags: "SERVER_NAME_TAGS",
  server_logon_token: "SERVER_LOGON_TOKEN",
  moderator_list: "SERVER_MODERATORS",
};

type V = Record<string, string | number | boolean | undefined>;
const BOOLS = new Set(["player_damage", "traffic", "force_speed_limiter", "name_tags"]);
const TEXT = ["lobby_name", "description", "welcome_message", "password", "server_logon_token"];

/**
 * The entrypoint writes the text values between double quotes into the .sii with no
 * escaping, so a quote, backslash or newline would corrupt the file. Refused up front.
 */
export function convoyValueError(values: V, touched: readonly string[]): string | null {
  for (const k of TEXT) {
    if (touched.includes(k) && /["\\\r\n]/.test(String(values[k] ?? ""))) return `${k} contains a quote or backslash, which the server's config file cannot hold.`;
  }
  if (touched.includes("moderator_list") && !/^[0-9,\s]*$/.test(String(values.moderator_list ?? ""))) return "Moderator list may only contain Steam64 IDs separated by commas.";
  return null;
}

export function convoyEnv(prefix: "ETS" | "ATS", values: V, touched: readonly string[]): Record<string, string> {
  const env: Record<string, string> = {};
  for (const k of touched) {
    const suffix = CONVOY_ENV_SUFFIX[k];
    if (!suffix) continue;
    const raw = values[k];
    env[`${prefix}_${suffix}`] = BOOLS.has(k)
      ? (raw === true || raw === "true" ? "true" : "false")
      : k === "moderator_list"
        ? String(raw ?? "").replace(/\s+/g, "")
        : String(raw ?? "");
  }
  return env;
}
EOF
