import type { GameConfigApplierSpec } from "../game-config-appliers";

/**
 * Insurgency: Sandstorm (andrewmhub/insurgency-sandstorm) — PURE half.
 *
 * Read off the image's entrypoint.sh: the server is exec'd as
 *   InsurgencyServer-Linux-Shipping $LAUNCH_SERVER_ENV -hostname="$HOSTNAME" -Port=.. -QueryPort=..
 * ($LAUNCH_SERVER_ENV is word-split, no globbing). So:
 *  - serverName -> env HOSTNAME
 *  - mapScenario, password, maxPlayers -> ONE env var LAUNCH_SERVER_ENV: the travel URL
 *    `Map?Scenario=..?Game=..?password=..?MaxPlayers=..` followed by launch args
 *    (the image README's own example uses exactly `?password=` and `?MaxPlayers=`).
 *    Any extra `-arg` tokens already in the variable (mods, mutators) are preserved.
 * All of these are read at server start, so a save recreates the container.
 */
export const SANDSTORM_SPEC: GameConfigApplierSpec = {
  family: "sandstorm",
  fields: {
    serverName: { when: "recreate" },
    password: { when: "recreate", secret: true },
    maxPlayers: { when: "recreate" },
    mapScenario: { when: "recreate", note: "Takes the form Map?Scenario=Scenario_...?Game=Mode, no spaces." },
  },
};

export const SANDSTORM_CONTAINER = "sandstorm";
/** Map name, then ?Key=Value options; no whitespace, no other punctuation. */
export const SANDSTORM_MAP_PATTERN = "^[A-Za-z0-9_]+(\\?[A-Za-z0-9_]+=[A-Za-z0-9_.-]+)*$";

type V = Record<string, string | number | boolean | undefined>;

export function sandstormValueError(values: V, touched: readonly string[]): string | null {
  if (touched.includes("mapScenario") && !new RegExp(SANDSTORM_MAP_PATTERN).test(String(values.mapScenario ?? "").trim())) {
    return "Map & Scenario must look like Map?Scenario=Scenario_Name?Game=Mode (letters, digits and underscores only).";
  }
  if (touched.includes("password") && /[\s?]/.test(String(values.password ?? "").trim())) return "The server password cannot contain spaces or question marks.";
  return null;
}

/** Strip any `?Option=` from a travel URL (case-insensitive key). */
function dropOption(url: string, key: string): string {
  return url.split("?").filter((p, i) => i === 0 || p.split("=")[0].toLowerCase() !== key.toLowerCase()).join("?");
}

/**
 * Compose LAUNCH_SERVER_ENV from the settings. `existing` (the container's current value, if any)
 * supplies whatever the settings do not own: the launch args, and for a field that is not being
 * changed, its current value. Pass touched = all four to build a fresh value.
 */
export function composeLaunchEnv(values: V, touched: readonly string[], existing: string | null): string {
  const toks = (existing ?? "").trim().split(/\s+/).filter(Boolean);
  const hasUrl = toks.length > 0 && !toks[0].startsWith("-");
  const args = hasUrl ? toks.slice(1) : toks;
  let url = hasUrl ? toks[0] : String(values.mapScenario ?? "").trim();
  if (touched.includes("mapScenario")) {
    // Keep the options the settings own out of the new map string, then re-add below.
    url = String(values.mapScenario ?? "").trim();
  }
  const ownsPw = touched.includes("password") || !hasUrl;
  const ownsMax = touched.includes("maxPlayers") || !hasUrl;
  // A new map string is built without our options, so carry the existing ones over if not touched.
  if (hasUrl && touched.includes("mapScenario")) {
    for (const o of existingOptions(toks[0], ["password", "MaxPlayers"])) {
      if (o.key.toLowerCase() === "password" && !touched.includes("password")) url = dropOption(url, "password") + `?${o.raw}`;
      if (o.key.toLowerCase() === "maxplayers" && !touched.includes("maxPlayers")) url = dropOption(url, "MaxPlayers") + `?${o.raw}`;
    }
  }
  if (ownsPw) {
    url = dropOption(url, "password");
    const pw = String(values.password ?? "").trim();
    if (pw) url += `?password=${pw}`;
  }
  if (ownsMax) {
    url = dropOption(url, "MaxPlayers");
    url += `?MaxPlayers=${Math.trunc(Number(values.maxPlayers ?? 10))}`;
  }
  return [url, ...args].join(" ");
}

function existingOptions(url: string, keys: string[]): { key: string; raw: string }[] {
  return url.split("?").slice(1).map((p) => ({ key: p.split("=")[0], raw: p })).filter((o) => keys.some((k) => k.toLowerCase() === o.key.toLowerCase()));
}

/**
 * Bake the settings into the provisioning script (fresh install / reinstall): adds
 * `-e LAUNCH_SERVER_ENV=...` (the template ships none) before the first `-v`.
 * Returns the script unchanged if it is not the sandstorm docker-run shape.
 */
export function applySandstormSetup(setupScript: string, values: V | null | undefined): string {
  if (!values || !/andrewmhub\/insurgency-sandstorm/.test(setupScript)) return setupScript;
  if (sandstormValueError(values, ["mapScenario", "password"])) return setupScript;
  const launch = composeLaunchEnv(values, ["mapScenario", "password", "maxPlayers"], null).replace(/'/g, `'\\''`);
  const flag = `-e LAUNCH_SERVER_ENV='${launch}'`;
  const existing = /-e\s+LAUNCH_SERVER_ENV=(?:'[^']*'|"[^"]*"|\S*)/;
  if (existing.test(setupScript)) return setupScript.replace(existing, () => flag);
  return setupScript.replace(/(docker run [^\n]*?) (-v )/, (_m, a: string, b: string) => `${a} ${flag} ${b}`);
}
EOF

