import type { GameConfigApplierSpec } from "../../lib/game-config-appliers";
import type { ApplierContext, ApplyOutcome, GameConfigApplier } from "./types";
import { shq } from "./types";
import { recreateWithEnv } from "./kit/env-recreate";

/**
 * Applier factory for families whose whole config is container ENV (arma reforger,
 * ETS2, ATS, Sandstorm). `envFor` maps the touched schema fields to env changes (or
 * returns {error} to refuse a value that cannot be represented); the factory does the
 * recreate-with-env swap (kit/env-recreate: old container kept until the new one is
 * verified, rolled back on any failure, stopped servers stay stopped).
 */
export type EnvFamily = {
  spec: GameConfigApplierSpec;
  container: string;
  /** What to call the thing in customer-facing sentences. */
  label: string;
  envFor(ctx: ApplierContext, currentEnv: Map<string, string>): Record<string, string> | { error: string };
};

async function currentEnv(ctx: ApplierContext, container: string): Promise<Map<string, string>> {
  const out = new Map<string, string>();
  const r = await ctx.guest.exec(`docker inspect ${shq(container)} --format '{{json .}}'`);
  if (r.code !== 0) return out;
  try {
    for (const e of (JSON.parse(r.stdout.trim()).Config?.Env ?? []) as string[]) {
      const i = e.indexOf("=");
      if (i > 0) out.set(e.slice(0, i), e.slice(i + 1));
    }
  } catch {
    /* an unreadable inspect just means no current env; recreateWithEnv re-reads and fails safely */
  }
  return out;
}

export function envFamilyApplier(f: EnvFamily): GameConfigApplier {
  async function apply(ctx: ApplierContext): Promise<ApplyOutcome> {
    const env = f.envFor(ctx, await currentEnv(ctx, f.container));
    if ("error" in env && typeof env.error === "string" && Object.keys(env).length === 1) {
      return { ok: false, applied: [], notes: [env.error, "Nothing was changed on your server."] };
    }
    const r = await recreateWithEnv(ctx.guest, {
      container: f.container,
      unit: ctx.unit,
      env: env as Record<string, string>,
      envFile: `/root/${f.container}.env`,
      waitPort: ctx.waitPort,
    });
    if (r.status === "failed") return { ok: false, applied: [], notes: [r.note] };
    if (r.status === "noop") return { ok: true, applied: [], notes: [`${f.label} already matched these settings — nothing to change.`] };
    const applied = [`Applied ${ctx.touched.join(", ")} to ${f.label} and restarted it with the new settings.`];
    const notes = [...r.notes];
    notes.push(
      r.wasActive
        ? "Your server restarted briefly — connected players were disconnected and can rejoin now."
        : "Your server is stopped, so the new settings take effect when you start it.",
    );
    return { ok: true, applied, notes, restarted: r.wasActive };
  }
  return { spec: f.spec, apply };
}
EOF
