import { SANDSTORM_SPEC, SANDSTORM_CONTAINER, composeLaunchEnv, sandstormValueError } from "../../lib/game-applier-specs/sandstorm";
import { envFamilyApplier } from "./env-family";

/**
 * Insurgency: Sandstorm: env-recreate of HOSTNAME and LAUNCH_SERVER_ENV (map/password/max players
 * composed into one travel URL, existing launch args preserved). See lib/game-applier-specs/sandstorm.ts.
 */
export const sandstormApplier = envFamilyApplier({
  spec: SANDSTORM_SPEC,
  container: SANDSTORM_CONTAINER,
  label: "Insurgency: Sandstorm",
  envFor: (ctx, cur) => {
    const err = sandstormValueError(ctx.values, ctx.touched);
    if (err) return { error: err };
    const env: Record<string, string> = {};
    if (ctx.touched.includes("serverName")) env.HOSTNAME = String(ctx.values.serverName ?? "");
    if (ctx.touched.some((k) => k !== "serverName")) env.LAUNCH_SERVER_ENV = composeLaunchEnv(ctx.values, ctx.touched, cur.get("LAUNCH_SERVER_ENV") ?? null);
    return env;
  },
});
