import { fakeGuest, type FakeOpts } from "./_fake-docker-guest";
import { validateConfig } from "../lib/game-config";
import { runApplier } from "../worker/game-config-appliers/run";
import type { GameConfigApplier } from "../worker/game-config-appliers/types";

/** A fake guest whose game container is reshaped to look like a given image's container. */
export function guestFor(container: string, c: { image: string; env: string[]; cmd?: string[]; binds: string[]; ports: Record<string, { HostIp: string; HostPort: string }[]> }, opts: FakeOpts = {}) {
  const g = fakeGuest({ ...opts, container, unit: `${container}.service` });
  const cur = g.containers.get(container)!;
  g.containers.set(container, { ...cur, image: c.image, env: ["PATH=/usr/bin", ...c.env], cmd: c.cmd ?? [], binds: c.binds, ports: c.ports, running: g.st.active });
  return g;
}

export function valuesFor(family: string, over: Record<string, string | number | boolean> = {}) {
  const v = validateConfig(family, over);
  if (!v.ok) throw new Error(v.error);
  return v.values;
}

export function runFor(applier: GameConfigApplier, g: ReturnType<typeof fakeGuest>, values: Record<string, string | number | boolean>, changed: string[] | undefined, restartRequested = false) {
  return runApplier(applier, { server: { id: "s1" }, values, changed, restartRequested, guest: g.guest, unit: g.unit, waitPort: async () => ({ ok: true }) });
}

/** The env of the container named `name` as a map. */
export function envOf(g: ReturnType<typeof fakeGuest>, name: string): Map<string, string> {
  const m = new Map<string, string>();
  for (const e of g.containers.get(name)!.env) {
    const i = e.indexOf("=");
    m.set(e.slice(0, i), e.slice(i + 1));
  }
  return m;
}
EOF
