  assert.equal(composeLaunchEnv({ mapScenario: "Farmhouse?Scenario=Scenario_Farmhouse_Push_Security?Game=Push" }, ["mapScenario"], ex), `Farmhouse?Scenario=Scenario_Farmhouse_Push_Security?Game=Push?password=old?MaxPlayers=12 -Mods -ModList=Mods.txt -mutators=A,B`);
  // an env that holds only args (no travel URL) gets a full URL in front
  assert.equal(composeLaunchEnv({ mapScenario: MAP, password: "", maxPlayers: 8 }, ["maxPlayers"], "-NoEAC"), `${MAP}?MaxPlayers=8 -NoEAC`);
});

