cat > test/cfg-dayz.test.ts <<'EOF'
import { test } from "node:test";
import assert from "node:assert/strict";
import { dayzApplier } from "../worker/game-config-appliers/dayz";
import { DAYZ_SPEC, DAYZ_CFG_PATH, patchDayzCfg, readDayzCfg } from "../lib/game-applier-specs/dayz";
import { GAME_CONFIG_SCHEMAS, validateConfig } from "../lib/game-config";
import { guestFor, valuesFor, runFor } from "./_cfg-misc-helpers";

// Shape of the file ich777's start script creates (Bohemia's template + its three sed seeds), incl. the real traps.
const CFG = `hostname = "Docker DayZ";  // Server name
password = "Docker";              // Password to connect to the server
passwordAdmin = "adminDocker";         // Password to become a server admin

maxPlayers = 60;            // Maximum amount of players

verifySignatures = 2;       // Verifies .pbos against .bisign files. (only 2 is supported)
loginQueueMaxPlayers=500;       // The maximum number of players that can wait in login queue
instanceId = 1;             // DayZ server instance id
steamQueryPort = 2305;      // defines Steam query port

class Missions
{
    class DayZ
    {
        template="dayzOffline.chernarusplus"; // Mission to load on server startup.
    };
};
`;
const mk = (files: Record<string, string> = { [DAYZ_CFG_PATH]: CFG }, o = {}) => guestFor("dayz", { image: "ich777/steamcmd:dayz", env: [], binds: [], ports: {} }, { files, ...o });
const read = (g: ReturnType<typeof mk>) => g.files.get(DAYZ_CFG_PATH)!;

test("all 5 schema fields are mapped, all restart", () => {
  assert.deepEqual(GAME_CONFIG_SCHEMAS.dayz.fields.map((f) => f.key).sort(), Object.keys(DAYZ_SPEC.fields).sort());
  for (const f of Object.values(DAYZ_SPEC.fields)) assert.equal(f.when, "restart");
});

test("each field is written to serverDZ.cfg; comments and every other key survive", async () => {
  const cases: [string, string | number | boolean, RegExp][] = [
    ["hostname", "Nxeon Chernarus", /^hostname = "Nxeon Chernarus";  \/\/ Server name$/m],
    ["password", "join-pw-1", /^password = "join-pw-1";\s+\/\/ Password to connect/m],
    ["passwordAdmin", "adm-pw-2", /^passwordAdmin = "adm-pw-2";\s+\/\/ Password to become/m],
    ["maxPlayers", 37, /^maxPlayers = 37;\s+\/\/ Maximum amount of players$/m],
    ["missionTemplate", "dayzOffline.enoch", /template="dayzOffline\.enoch"; \/\/ Mission to load/],
  ];
  for (const [field, value, re] of cases) {
    const g = mk();
    const out = await runFor(dayzApplier, g, valuesFor("dayz", { [field]: value }), [field]);
    assert.equal(out.ok, true, field);
    assert.match(read(g), re, field);
    assert.match(read(g), /^loginQueueMaxPlayers=500;/m, "loginQueueMaxPlayers untouched");
    assert.match(read(g), /^steamQueryPort = 2305;/m);
    assert.equal(g.log.some((l) => /systemctl (restart|stop)|docker (restart|stop)/.test(l)), false, "the applier never restarts; the job layer does");
  }
});

test("only touched fields are written (a stale seeded password is not overwritten by an untouched field)", async () => {
  const g = mk();
  await runFor(dayzApplier, g, valuesFor("dayz", { hostname: "H", password: "zzz" }), ["hostname"]);
  assert.match(read(g), /^password = "Docker";/m);
});

test("idempotent: same values again write nothing", async () => {
  const g = mk();
