test("secrets are redacted and never on a command line", async () => {
  const g = mk();
  const out = await runFor(dayzApplier, g, valuesFor("dayz", { password: "Hunter2-Zq", passwordAdmin: "AdminSecret77" }), ["password", "passwordAdmin"]);
