  assert.deepEqual(readDayzCfg(read(g), ["password", "passwordAdmin", "maxPlayers", "missionTemplate"]), { password: "Hunter2-Zq", passwordAdmin: "AdminSecret77", maxPlayers: "60", missionTemplate: "dayzOffline.chernarusplus" });
});

test("quotes, backslashes and semicolons cannot be written (schema + applier)", async () => {
  for (const bad of ['a"b', "a\\b", "a;b"]) assert.equal(validateConfig("dayz", { hostname: bad }).ok, false, bad);
  const g = mk();
  const out = await runFor(dayzApplier, g, { ...valuesFor("dayz"), hostname: 'x"; evil = 1; //' }, ["hostname"]);
  assert.equal(out.ok, false);
  assert.equal(read(g), CFG);
});

test("patchDayzCfg throws rather than appending guessed keys", () => {
