});

test("a field the spec does not handle is saved-only", async () => {
  const out = await runFor(dayzApplier, mk(), valuesFor("dayz"), ["hostname", "bogus"]);
  assert.match(out.notes.join(" "), /Saved but not applied.*bogus/);
});
